// A simple helper: true iff n is a positive power of two.
fn is_2_pow(n: i64) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

/// Returns the lower-bound insertion position of `x` within `a[lo..hi)`.
/// That is, returns `k` in [lo, hi] such that:
/// - for all r in [lo, k): a[r] < x
/// - for all r in [k, hi): a[r] >= x
///
/// Preconditions (assumed by the problem statement / caller):
/// - 0 <= lo <= hi <= a.len()
/// - a[lo..hi) is sorted in nondecreasing order
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    debug_assert!(lo <= hi);
    debug_assert!(hi <= a.len());

    let mut l = lo;
    let mut r = hi; // exclusive

    while l < r {
        let m = l + (r - l) / 2;
        if a[m] < x {
            l = m + 1;
        } else {
            r = m;
        }
    }

    l
}

/// Returns the lower-bound insertion position of `x` within the first 1000 elements.
/// Result `k` is in [0, 1000].
///
/// Preconditions (assumed by the problem statement / caller):
/// - a.len() >= 1000
/// - a[0..1000) is sorted in nondecreasing order
fn search_1000(a: &[i32], x: i32) -> usize {
    debug_assert!(a.len() >= 1000);
    search_range_helper(a, x, 0, 1000)
}

